const msg = ($input.item.json.body.message || '').toLowerCase();
let reply = '';
let carousel = [];

if (msg.includes('gratis')) {
  reply = '¡Por supuesto! En **SimplyOver** contamos con múltiples overlays gratuitos optimizados para OBS Studio. Aquí tienes algunos populares para descargar de inmediato:';
  carousel = [
    { name: 'Minimalist Dark Bar', price: 'Gratis', url: '/overlay/minimalist-dark' },
    { name: 'Neon Cyber Alerts', price: 'Gratis', url: '/overlay/neon-cyber-alerts' },
    { name: 'Clean Webcam Border', price: 'Gratis', url: '/overlay/clean-webcam-border' }
  ];
} else if (msg.includes('cyberpunk')) {
  reply = '¡El estilo Cyberpunk es espectacular! ⚡ Aquí tienes overlays futuristas de neón listos para tu transmisión:';
  carousel = [
    { name: 'Night City Full HUD', price: '$1500', url: '/overlay/night-city-hud' },
    { name: 'Glitch Synth Alerts', price: 'Gratis', url: '/overlay/glitch-synth-alerts' }
  ];
} else {
  reply = 'SimplyOver es el marketplace especializado para streamers de OBS Studio. Puedes descargar overlays, publicar tus diseños [BTN:PUBLISH], diseñarlos en el editor web [BTN:WEB_EDITOR] o generarlos con IA [BTN:AI_STUDIO]. ¿Qué te gustaría hacer?';
}

return {
  json: {
    reply,
    carousel,
    source: 'static_cache',
    assistant: 'SimplyOver AI'
  }
};

const body = $input.item.json.body || {};
