const data = $input.item.json;
let rawReply = data?.choices?.[0]?.message?.content || data?.message?.content || data?.content || '¡Hola! Soy tu asistente de SimplyOver. ¿Qué estilo de overlay te gustaría agregar a tu stream?';

return {
  json: {
    rawReply,
    engine: 'fallback_spider'
  }
};

let text = $input.item.json.rawReply || '';

// 1. Sanitización de nombres de proveedores (Marca Blanca Estricta)
text = text.replace(/\b(google\s+gemini|gemini|spideria|spiderweb|chatgpt|openai)\b/gi, 'SimplyOver AI');

// 2. Inyección de botones de acción interactivos de SimplyOver
const lower = text.toLowerCase();
if ((lower.includes('crear') || lower.includes('diseñar') || lower.includes('editor')) && !text.includes('[BTN:WEB_EDITOR]')) {
  text += '\n\n[BTN:WEB_EDITOR]';
}
if ((lower.includes('publicar') || lower.includes('vender') || lower.includes('subir')) && !text.includes('[BTN:PUBLISH]')) {
  text += '\n\n[BTN:PUBLISH]';
}
if ((lower.includes('inteligencia artificial') || lower.includes('generar')) && !text.includes('[BTN:AI_STUDIO]')) {
  text += '\n\n[BTN:AI_STUDIO]';
}

return {
  json: {
    reply: text,
    carousel: [],
    assistant: 'SimplyOver AI',
    status: 'success'
  }
};
